#include <zephyr/mgmt/mgmt_enum.h>
#include <zephyr/mgmt/mgmt.h>
#include <tinycbor/cbor.h>

bool mgmt_enum_object(struct cbor_encoder *encoder, struct mgmt_enum_iter *iter)
{
    struct cbor_string key;
    struct cbor_string val;

    if (!cbor_encode_map_indefinite(encoder)) {
        return false;
    }

    while (iter->get_next(iter, &key, &val)) {
        if (!cbor_encode_text_string(encoder, key.ptr, key.len)) {
            return false;
        }
        /* If the value pointer is NULL, encode it as a CBOR null type. */
        /* This prevents potential buffer overflows if a get_next implementation */
        /* returns a NULL pointer with a non-zero length, or if an empty string */
        /* (NULL, 0) should semantically be a null value. */
        if (val.ptr == NULL) {
            if (!cbor_encode_null(encoder)) {
                return false;
            }
        } else {
            if (!cbor_encode_tstr(encoder, val.ptr, val.len)) {
                return false;
            }
        }
    }

    if (!cbor_encode_map_end(encoder, NULL)) {
        return false;
    }

    return true;
}

bool mgmt_enum_array(struct cbor_encoder *encoder, struct mgmt_enum_iter *iter)
{
    struct cbor_string key; /* Key is ignored for array enumeration */
    struct cbor_string val;

    if (!cbor_encode_array_indefinite(encoder)) {
        return false;
    }

    while (iter->get_next(iter, &key, &val)) {
        /* If the value pointer is NULL, encode it as a CBOR null type. */
        /* This prevents potential buffer overflows if a get_next implementation */
        /* returns a NULL pointer with a non-zero length, or if an empty string */
        /* (NULL, 0) should semantically be a null value. */
        if (val.ptr == NULL) {
            if (!cbor_encode_null(encoder)) {
                return false;
            }
        } else {
            if (!cbor_encode_tstr(encoder, val.ptr, val.len)) {
                return false;
            }
        }
    }

    if (!cbor_encode_array_end(encoder, NULL)) {
        return false;
    }

    return true;
}
